evidence.quote:
%if &byvar = none %then %do;

data xtemp;
set xtemp;
byvar = 1;
run;

%let byvar = xbyvar;

%end;

data LINK;
set NONGAAP.LINKTABLE;
if LINKENDDT lt '01JAN2000'd then delete;
if LINKDT gt '30JUN2006'd then delete;
run;

proc sort data = LINK nodupkey out = LINK; by TIC; run;

data NONGAAP;
set NONGAAP.NONGAAPDATA     ;
if TICKER = '' then delete;
if DATE lt '01Jan2000'd then delete;
if DATE gt '30Jun2006'd then delete;
if DATE gt '01JAN2003'd and DATE lt '30JUN2003'd then delete;
rename TICKER = TIC DATE = RDQ QUARTER = FQTR YEAR = FYEARQ ;
if DATE le '28MAR2003'd then REG_G = 0;
else if DATE gt '28MAR2003'd then REG_G = 1;
run;

proc sort data = NONGAAP nodupkey out = NONGAAP; by TIC FYEARQ FQTR; run;

data NONGAAP2;
merge NONGAAP(in=a) LINK;
if a ; by TIC; if RDQ ge LINKDT and RDQ le LINKENDDT;
run;

data CSTAT;
set NONGAAP.COMPUSTATDATA;
if DPQ = '.' then DPQ = 0;
if DOQ = '.' then DOQ = 0;
if XIQ = '.' then XIQ = 0;
if GLPQ = '.' then GLPQ = 0;
if GDWLIAQ = '.' then GDWLIAQ = 0;
if NRTXTQ = '.' then NRTXTQ = 0;
if SPIQ = '.' then SPIQ = 0;
if XRDQ = '.' then XRDQ = 0;
if RCPQ = '.' then RCPQ = 0;
if STKCPAQ = '.' then STKCPAQ = 0;
if WDPQ = '.' then WDPQ = 0;
OSPIQ = SPIQ - GLPQ - GDWLIAQ - RCPQ - WDPQ;
STKCPPQ = STKCPAQ/(1-0.35);
GDWLIPQ = GDWLIAQ/(1-0.35);
EXCLUSIONS = -DPQ + DOQ + XIQ + GLPQ + GDWLIPQ + NRTXTQ - XRDQ + RCPQ - STKCPPQ + WDPQ +
OSPIQ;
EXCLUSIONS_ASSETS = Exclusions/ATQ;
EXCLUSIONS_REV = Exclusions/SALEQ;
SIZE = CSHOQ*PRCCQ;
MB = (PRCCQ*CSHOQ)/CEQQ;
LOGSIZE = log(SIZE);
LOGMB = log(1+MB);
CUSIP = substr(CUSIP,1,8);
if NIQ gt 0 then LOSS = 0 ;
else if NIQ le 0 then LOSS = 1;
run;

proc sort data = NONGAAP2; by TIC FYEARQ FQTR; run;
proc sort data = CSTAT nodupkey out = CSTAT; by TIC FYEARQ FQTR; run;

data NONGAAP3;
merge NONGAAP2(in=a) CSTAT(in=b);
if a and b; by TIC DATAFQTR ;
CMONTH = month(datadate);
CYEAR = year(datadate);
rename LPERMNO = PERMNO;
run;

data CRSP;
set NONGAAP.CRSPDATA;
CRSP_PRICE=abs(PRC);
CYEAR = year(date);
CMONTH = month(date);
run;

proc sort data = NONGAAP3 nodupkey out=NONGAAP3; by PERMNO CYEAR CMONTH; run;
proc sort data = CRSP nodupkey out=CRSP; by PERMNO CYEAR CMONTH; run;

data NONGAAP4;
merge NONGAAP3 (in=a) CRSP (in=b);

if a and b; by PERMNO CYEAR CMONTH;
run;

data IBES;
set NONGAAP.IBESDATA;
DAYSTOGO = ANNDATS_ACT - STATPERS;
run;

Proc sort data=IBES    nodupkey out = IBES;   By OFTIC ANNDATS_ACT descending DAYSTOGO; Run;

Data IBES2;
Set IBES;
By OFTIC ANNDATS_ACT ;
If LAST.ANNDATS_ACT = 1;
If daystogo = '.' then delete; else if daystogo lt 0 then delete; else if daystogo gt 60
then delete;
if ANNDATS_ACT gt '30JUN2006'd then delete;
RMONTH = month(anndats_act);
RYEAR = year(anndats_act);
run;

proc sort data = IBES2 ; by CUSIP RYEAR RMONTH; run;
proc sort data = NONGAAP5 ;by CUSIP RYEAR RMONTH; run;

data NONGAAP6;
merge NONGAAP5(in=a) IBES2;
if a; by CUSIP RYEAR RMONTH; if NUMEST = '.' then NUMEST = 0;
logNUMEST = log(1+NUMEST);
run;

proc univariate data = xtemp noprint;
by &byvar;
var &vars;
output out = xtemp_pctl PCTLPTS = &pctl PCTLPRE = &vars PCTLNAME = L H;
run;

/*** Winsorize variables ***/
%winsor(dsetin=NONGAAP7, dsetout=NONGAAP8, byvar=none,
vars= LEV SALES LOSS LOGSIZE LOGMB NUMEST LOGNUMEST STDEV , type=winsor, pctl=1 99);

/* Remove observations with missing control variables */
data NONGAAP10;
set NONGAAP9;
if LOGMB = '.' then delete;
if LOGSIZE = '.' then delete;
if LEV = '.' then delete;
if LOGNUMEST = '.' then delete;
if EXCLUSIONS_ASSETS = '.' then delete;
if EXCLUSIONS_REV = '.' then delete;
if ATQ = '.' then delete;
if SALEQ = '.' then delete;
run;

/* Final Sample */
